// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }

    // fuzz parameters:
    // - address payer is used as the `from` argument to C.transfer
    // - uint256 v is the value forwarded as the `v` argument
    // - address[] memory tos is the list of recipients that C will call on caddress
    // We will supply the callee (recordingReverter) as the caddress by deploying it below.
    function testFuzz_property(address payer, uint256 v, address a0, address a1) public {
        // Keep tos length in {1,2} to keep the external call count small but >0
        address[] memory tos = new address[](2);
        tos[0] = a0;
        tos[1] = a1;
        // ensure tos entries are distinct-ish and nonzero to avoid accidental default behavior
        if (tos[0] == address(0)) tos[0] = address(1);
        if (tos[1] == address(0) || tos[1] == tos[0]) tos[1] = address(2);

        // Deploy a callee that implements the correct transferFrom(address,address,uint256) and records calls.
        // The correct (reference) contract will call this function by selector and succeed; the mutant uses a wrong selector
        // so the call to this callee will NOT match the selector and thus the low-level call will fail (return false)
        // causing the mutant's require(_s) to revert for some inputs. We drive C.transfer through the deployed callee.
        RecordingCallee rc = new RecordingCallee();

        // call c.transfer. We must observe that the reference ALWAYS succeeds (does not revert) for ANY inputs
        // where tos.length>0 and the callee implements transferFrom. We wrap the call to capture success vs revert.
        bool ok;
        try c.transfer(payer, address(rc), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: for any inputs with tos.length>0, the reference C should succeed (ok==true)
        // because rc implements the exact selector and will return true; the mutant with wrong selector will fail
        // for some fuzzed inputs (and the fuzzer can find such inputs) and thus this assertion distinguishes them.
        assertTrue(ok);
    }
}

// A callee that defines the exact function signature the reference C expects and records calls.
contract RecordingCallee {
    event Called(address from, address to, uint256 v);

    // must match selector bytes4(keccak256("transferFrom(address,address,uint256)"))
    function transferFrom(address from, address to, uint256 v) external returns (bool) {
        emit Called(from, to, v);
        return true;
    }
}
